mapper.update:
UPDATE ntf_delivery
SET status = 'SENT', external_ref = #{externalRef}, sent_at = #{sentAt}
WHERE delivery_id = #{deliveryId} AND status = 'PENDING'

UPDATE ntf_delivery
SET status = 'FAILED', last_error = #{lastError}
WHERE delivery_id = #{deliveryId} AND status = 'PENDING'

UPDATE ntf_delivery
SET attempts = attempts + 1, last_error = #{lastError}
WHERE delivery_id = #{deliveryId}
